import React, { useEffect, useMemo, useState } from "react";
import { db } from "../firebase/config";
import {
    collection,
    addDoc,
    onSnapshot,
    deleteDoc,
    doc,
    updateDoc,
    getDoc,
    serverTimestamp,
} from "firebase/firestore";
import { PROJECTS, ZONES } from "../utils/constants";
import jsPDF from "jspdf";
import html2canvas from "html2canvas";
import "./CalendarPage.css";





const handleExportPDF = async () => {
    const element = document.getElementById("calendarScrollX");

    if (!element) {
        alert("❌ 'calendarScrollX' elementi bulunamadı!");
        return;
    }





};



const getProjectDisplayName = (name) => {
    if (name.includes("Survivor")) return "SURVIVOR";
    if (name.includes("Exatlon") || name.includes("Exathlon")) {
        return name.includes("Greece") ? "EXATHLON" : "EXATLON";
    }
    return name;
};

const pad = (n) => (n < 10 ? `0${n}` : `${n}`);
const ymd = (d) =>
    `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;

const getZoneColors = (zone) => {
    switch (zone) {
        case "ZONE 1":
            return { bg: "rgb(177,57,40)", fg: "#fff" };     // kırmızı
        case "ZONE 2":
            return { bg: "rgb(63,124,181)", fg: "#fff" };    // mavi
        case "ZONE 3":
            return { bg: "rgb(255,206,18)", fg: "#111" };    // sarı
        case "ZONE 4":
            return { bg: "rgb(119,174,91)", fg: "#fff" };    // yeşil
        default:
            return { bg: "#bbb", fg: "#111" };
    }
};


export default function CalendarPage({ user }) {

    const [activeButton, setActiveButton] = useState("twoweek");
    const [selectedProjectFilter, setSelectedProjectFilter] = useState("all")
    const [events, setEvents] = useState([]);
    const [showAddEvent, setShowAddEvent] = useState(false);
    const [openAddEventModal, setOpenAddEventModal] = useState(false);
    const [form, setForm] = useState({
        project: "",
        zone: "",
        location: "",
        code: "",
        date: "",
        note: "",
        isDraft: false,
    });
    const [viewMode, setViewMode] = useState("twoweeks");

    // 🟢 Event modal için state'ler
    const [selectedEvent, setSelectedEvent] = useState(null);
    const [copiedEvent, setCopiedEvent] = useState(null);

    const handleDeleteEvent = async (id) => {
        if (!window.confirm("⚠️ Are you sure you want to delete this event?")) return;

        try {
            // 🔹 Kullanıcıdan silme nedeni al
            let reason = "";
            while (!reason) {
                reason = prompt("Please enter the reason for deleting this event:");
                if (reason === null) return; // iptal
                if (!reason.trim()) alert("Reason is required to log this deletion.");
            }

            // 🔹 Eski veriyi getir
            const ref = doc(db, "events", id);
            const snapshot = await getDoc(ref);
            const oldData = snapshot.exists() ? snapshot.data() : {};

            // 🔹 Sil
            await deleteDoc(ref);

            // 🔹 ChangeLogs’a detaylı kayıt ekle
            await addDoc(collection(db, "changeLogs"), {
                eventId: id,
                project: oldData.project || "UNKNOWN",
                zone: oldData.zone || "",
                location: oldData.location || "",
                oldDate: oldData.date || "",
                newDate: "(deleted)",
                reason,
                user: user?.email || "UNKNOWN",
                time: new Date().toLocaleString("tr-TR"),
                operation: "Deleted",
                status: "Deleted", // ✅ yeni alan
            });

            setSelectedEvent(null);
            alert("🗑️ Event deleted and logged successfully!");
        } catch (error) {
            console.error("Error deleting event:", error);
            alert("❌ Error while deleting event: " + error.message);
        }
    };
    // 🟢 Kart tıklanınca modal aç
    const handleOpenEvent = (ev) => {
        setSelectedEvent(ev);
    };

    const exportFullCalendarPDF = async () => {
        const element = document.getElementById("calendarScrollX");
        if (!element) return alert("Takvim bulunamadı!");

        element.scrollTo(0, 0);

        const canvas = await html2canvas(element, {
            scale: 2,
            useCORS: true,
            scrollX: 0,
            scrollY: 0,
            windowWidth: element.scrollWidth,
            windowHeight: element.scrollHeight,
        });

        const imgData = canvas.toDataURL("image/png");

        const pdf = new jsPDF({
            orientation: "landscape",
            unit: "px",
            format: [canvas.width, canvas.height],
        });

        pdf.addImage(imgData, "PNG", 0, 0, canvas.width, canvas.height);

        // 🌎 Dominik Cumhuriyeti saat dilimi
        const now = new Date();
        const options = {
            timeZone: "America/Santo_Domingo",
            year: "numeric",
            month: "2-digit",
            day: "2-digit",
            hour: "2-digit",
            minute: "2-digit",
            second: "2-digit",
            hour12: false,
        };

        const formatter = new Intl.DateTimeFormat("en-GB", options);
        const parts = formatter.formatToParts(now);
        const dateObj = Object.fromEntries(parts.map((p) => [p.type, p.value]));
        const fileName = `CalendarView_${dateObj.year}-${dateObj.month}-${dateObj.day}_${dateObj.hour}-${dateObj.minute}-${dateObj.second}.pdf`;

        pdf.save(fileName);
    };

    // 🟢 Etkinliği güncelle (tarih/note revize edildiğinde)
    const handleSaveRevisedEvent = async () => {
        if (!selectedEvent) return;

        try {
            // 🔹 Değişiklik nedeni iste
            let reason = "";
            while (!reason) {
                reason = prompt("Please enter the reason for this revision:");
                if (reason === null) return; // kullanıcı iptal etti
                if (!reason.trim()) alert("Reason is required to log the change.");
            }

            const ref = doc(db, "events", selectedEvent.id);
            const oldEvent = events.find((e) => e.id === selectedEvent.id);

            // 🔹 Güncellenecek veri
            const updatedData = {
                ...selectedEvent,
                isRevised: true,
                revisedAt: serverTimestamp(),
                revisedBy: user?.email || "UNKNOWN",
            };

            // 🔹 Firestore'da etkinliği güncelle
            await updateDoc(ref, updatedData);

            // 🔹 ChangeLogs koleksiyonuna kayıt ekle
            await addDoc(collection(db, "changeLogs"), {
                eventId: selectedEvent.id,
                project: selectedEvent.project || "UNKNOWN",
                zone: selectedEvent.zone || "",
                location: selectedEvent.location || "",
                oldDate: oldEvent?.date || "(unknown)",
                newDate: selectedEvent.date,
                reason,
                user: user?.email || "UNKNOWN",
                time: new Date().toLocaleString("tr-TR"),
                operation: "Updated", // ✅ tabloya yazılacak işlem
                status: "Updated", // ✅ yeni alan (raporlamalar için)
            });

            // 🔹 UI güncelle
            setEvents((prev) =>
                prev.map((ev) =>
                    ev.id === selectedEvent.id ? { ...ev, ...updatedData } : ev
                )
            );

            alert("✅ Event updated and logged to Change Logs!");
            setSelectedEvent(null);
        } catch (err) {
            console.error("Revision Error:", err);
            alert("❌ Error while saving revision: " + err.message);
        }
    };



    // 🟢 Kopyala
    const handleCopyEvent = () => {
        setCopiedEvent(selectedEvent);
        alert("Event copied! Click another date to paste.");
        setSelectedEvent(null);
    };



    /* Firestore listener */
    useEffect(() => {
        const unsub = onSnapshot(collection(db, "events"), (snap) => {
            setEvents(snap.docs.map((d) => ({ id: d.id, ...d.data() })));
        });
        return () => unsub();
    }, []);

    /* Tarih aralığı */
    const days = useMemo(() => {
        const today = new Date();
        const start = new Date(today);
        const end = new Date(today);
        if (viewMode === "week") {
            start.setDate(today.getDate() - 1);
            end.setDate(today.getDate() + 7);
        } else {
            start.setDate(today.getDate() - 7);
            end.setDate(today.getDate() + 14);
        }
        const arr = [];
        const cursor = new Date(start);
        while (cursor <= end) {
            arr.push(new Date(cursor));
            cursor.setDate(cursor.getDate() + 1);
        }
        return arr;
    }, [viewMode]);

    /* Event ekleme */
    const handleAddEvent = async (e) => {
        e.preventDefault();

        // 🔹 Dinamik zorunlu alan kontrolü
        if (!form.project) {
            alert("Please select a Project.");
            return;
        }

        if (form.isReality) {
            // 🎬 Reality gününde sadece Project + Date zorunlu
            if (!form.date) {
                alert("Please select a Date for Reality Day.");
                return;
            }
        } else {
            // 📍 Out of Hub seçili değilse Zone & Location zorunlu
            if (!form.outOfHub) {
                if (!form.zone) {
                    alert("Please select a Zone.");
                    return;
                }
                if (!form.location) {
                    alert("Please select a Location.");
                    return;
                }
            }

            // Out of Hub değilse Code zorunlu
            if (!form.code) {
                alert("Please enter Project Code.");
                return;
            }

            if (!form.date) {
                alert("Please select a Date.");
                return;
            }
        }

        const title = `${form.zone || "N/A"} / ${form.location || form.outOfHubLocation || "N/A"} / ${form.code || ""}`;

        try {
            // 🔸 1️⃣ Firestore'a kaydet
            const newEventRef = await addDoc(collection(db, "events"), {
                ...form,
                title,
                user: user?.email || "UNKNOWN",
                createdAt: serverTimestamp(),
                isRevised: false,
            });

            // 🔸 2️⃣ ChangeLogs'a kayıt ekle
            await addDoc(collection(db, "changeLogs"), {
                eventId: newEventRef.id,
                project: form.project || "UNKNOWN",
                zone: form.zone || "",
                location: form.location || form.outOfHubLocation || "",
                oldDate: "(none)",
                newDate: form.date,
                reason: form.isReality ? "Reality day event created" : "New event created",
                user: user?.email || "UNKNOWN",
                time: new Date().toLocaleString("tr-TR"),
                operation: "Created",
                status: "Created",
            });

            // 🔸 3️⃣ Temizle
            alert("✅ Event successfully added and logged!");
            setForm({
                project: "",
                zone: "",
                location: "",
                code: "",
                date: "",
                note: "",
                endingCode: "",
                outOfHub: false,
                outOfHubLocation: "",
                isReality: false,
                isDraft: false,
            });
            setShowAddEvent(false);
        } catch (err) {
            console.error("Add Event Error:", err);
            alert("❌ Error adding event: " + err.message);
        }
    };



    /* Drag & Drop */
    const onDragStart = (e, ev) => {
        e.dataTransfer.setData("application/json", JSON.stringify(ev));
    };


    const onDropToCell = async (e, dateStr, project) => {

        if (copiedEvent) {
            const newEvent = { ...copiedEvent, date: dateStr, isRevised: false };
            delete newEvent.id;
            await addDoc(collection(db, "events"), newEvent);
            alert("Event pasted successfully!");
            setCopiedEvent(null);
            return;
        }
        e.preventDefault();
        const raw = e.dataTransfer.getData("application/json");
        if (!raw) return;

        const { id, date: oldDate, zone, location, user: oldUser } = JSON.parse(raw);

        // 🔹 Aynı güne taşımayı engelle
        if (oldDate === dateStr && project === project) return;

        // 🔹 Kullanıcıdan onay al
        const confirmMove = window.confirm(
            `Move event "${zone} / ${location}" to ${project} - ${dateStr}?`
        );
        if (!confirmMove) return;

        // 🔹 Sebep iste (boş bırakılamaz)
        let reason = "";
        while (!reason) {
            reason = prompt("Please enter the reason for this change:");
            if (reason === null) return; // İptal edildi
            if (!reason.trim()) alert("Reason is required to log the change.");
        }

        // 🔹 Güncelleme işlemi
        const eventRef = doc(db, "events", id);
        await updateDoc(eventRef, {
            date: dateStr,
            project,
            isRevised: true,
            revisedAt: serverTimestamp(),
            revisedBy: user?.email || "UNKNOWN",
        });

        // 🔹 Change log’a yaz
        await addDoc(collection(db, "changeLogs"), {
            project,
            zone,
            location,
            oldDate,
            newDate: dateStr,
            reason,
            user: user?.email || oldUser || "UNKNOWN",
            time: new Date().toLocaleString(),
        });

        alert("Event moved successfully and logged in Change Logs.");
    };


    return (
        <div style={{ textAlign: "center", paddingBottom: 40 }}>
            {/* === BUTONLAR === */}
            <div
                style={{
                    display: "flex",
                    justifyContent: "center",
                    gap: 10,
                    flexWrap: "wrap",
                    marginBottom: 20,
                }}
            >
                <button
                    onClick={() => {
                        setShowAddEvent(true);
                        setActiveButton("add"); // 🔹 aktif buton: ADD EVENT
                    }}
                    style={{
                        background: viewMode === "add" ? "#6c757d" : "#e0e0e0",
                        color: viewMode === "add" ? "white" : "black",
                        fontWeight: "bold",
                        border: "none",
                        padding: "10px 18px",
                        borderRadius: 8,
                        cursor: "pointer",
                    }}
                >
                    ➕ ADD EVENT
                </button>
                <button
                    onClick={() => setViewMode("week")}
                    style={{
                        background: viewMode === "week" ? "#6c757d" : "#e0e0e0",
                        color: viewMode === "week" ? "white" : "black",
                        border: "none",
                        padding: "10px 18px",
                        borderRadius: 8,
                        cursor: "pointer",
                    }}
                >
                    1 WEEK
                </button>
                <button
                    onClick={() => setViewMode("twoweeks")}
                    style={{
                        background: viewMode === "twoweeks" ? "#6c757d" : "#e0e0e0",
                        color: viewMode === "twoweeks" ? "white" : "black",
                        border: "none",
                        padding: "10px 18px",
                        borderRadius: 8,
                        cursor: "pointer",
                    }}
                >
                    3 WEEKS
                </button>

                <button
                    onClick={exportFullCalendarPDF}
                    style={{
                        background: "#f8f9fa",
                        color: "#000",
                        fontWeight: 600,
                        padding: "6px 12px",
                        borderRadius: 6,
                        border: "1px solid #ccc",
                        cursor: "pointer",
                        fontSize: 12,
                    }}
                >
                    📄 EXPORT PDF
                </button>
            </div>


            {/* === EVENT EKLEME === */}
            {/* === EVENT EKLEME === */}
            {showAddEvent && (
                <div
                    style={{
                        position: "fixed",
                        top: 0,
                        left: 0,
                        width: "100vw",
                        height: "100vh",
                        background: "rgba(0,0,0,0.55)",
                        display: "flex",
                        alignItems: "center",
                        justifyContent: "center",
                        zIndex: 9999,
                    }}
                >
                    <div
                        style={{
                            background: "#fff",
                            borderRadius: 12,
                            padding: "18px 20px",
                            maxHeight: "90vh",
                            width: "500px",
                            overflowY: "auto",
                            boxShadow: "0 4px 20px rgba(0,0,0,0.35)",
                            animation: "popupEase .15s ease-out",
                            position: "relative",
                        }}
                    >
                        {/* X (kapat) butonu */}
                        <button
                            type="button"
                            onClick={() => setShowAddEvent(false)}
                            style={{
                                position: "absolute",
                                top: 10,
                                right: 12,
                                background: "transparent",
                                border: "none",
                                fontSize: 22,
                                fontWeight: "bold",
                                cursor: "pointer",
                                color: "#000",
                            }}
                        >
                            ✕
                        </button>

                        {/* === EVENT EKLEME FORMUN === */}
                        <form onSubmit={handleAddEvent} style={{ width: "100%" }}>

                            {/* === PROJECT === */}
                            <label style={{ display: "block", fontWeight: 600, marginBottom: 4 }}>
                                PROJECT <span style={{ color: "red" }}>*</span>
                            </label>
                            <select
                                value={form.project}
                                onChange={(e) => setForm({ ...form, project: e.target.value })}
                                style={{
                                    width: "100%",
                                    padding: "9px 8px",
                                    fontSize: 13.5,
                                    borderRadius: 6,
                                    marginBottom: 8,
                                }}
                            >
                                <option value="">Select Project</option>
                                {PROJECTS.map((p) => (
                                    <option key={p.name} value={p.name}>
                                        {p.name}
                                    </option>
                                ))}
                            </select>

                            {/* === Eğer Reality aktif değilse geri kalan alanlar gösterilecek === */}
                            {!form.isReality && (
                                <>
                                    {/* === ZONE === */}
                                    <label style={{ display: "block", fontWeight: 600, marginBottom: 4 }}>
                                        ZONE{" "}
                                        {!form.outOfHub && (
                                            <span style={{ color: "red" }}>*</span>
                                        )}
                                    </label>
                                    <select
                                        value={form.zone}
                                        onChange={(e) => setForm({ ...form, zone: e.target.value })}
                                        disabled={form.outOfHub}
                                        style={{
                                            width: "100%",
                                            padding: "9px 8px",
                                            fontSize: 13.5,
                                            borderRadius: 6,
                                            marginBottom: 8,
                                            backgroundColor: form.outOfHub ? "#f1f1f1" : "white",
                                            cursor: form.outOfHub ? "not-allowed" : "pointer",
                                        }}
                                    >
                                        <option value="">Select Zone</option>
                                        {Object.keys(ZONES).map((z) => (
                                            <option key={z} value={z}>
                                                {z}
                                            </option>
                                        ))}
                                    </select>

                                    {/* === LOCATION === */}
                                    <label style={{ display: "block", fontWeight: 600, marginBottom: 4 }}>
                                        LOCATION{" "}
                                        {!form.outOfHub && (
                                            <span style={{ color: "red" }}>*</span>
                                        )}
                                    </label>
                                    <select
                                        value={form.location}
                                        onChange={(e) => setForm({ ...form, location: e.target.value })}
                                        disabled={form.outOfHub}
                                        style={{
                                            width: "100%",
                                            padding: "9px 8px",
                                            fontSize: 13.5,
                                            borderRadius: 6,
                                            marginBottom: 8,
                                            backgroundColor: form.outOfHub ? "#f1f1f1" : "white",
                                            cursor: form.outOfHub ? "not-allowed" : "pointer",
                                        }}
                                    >
                                        <option value="">Select Location</option>
                                        {form.zone &&
                                            ZONES[form.zone].map((loc) => (
                                                <option key={loc} value={loc}>
                                                    {loc}
                                                </option>
                                            ))}
                                    </select>

                                    {/* === OUT OF HUB === */}
                                    <div
                                        style={{
                                            display: "flex",
                                            alignItems: "center",
                                            gap: 10,
                                            padding: "10px 12px",
                                            borderRadius: 8,
                                            border: form.outOfHub ? "2px solid #007bff" : "1px solid #ccc",
                                            background: form.outOfHub
                                                ? "rgba(0,123,255,0.05)"
                                                : "#f9f9f9",
                                            transition: "all 0.3s ease",
                                            marginBottom: 8,
                                        }}
                                    >
                                        <input
                                            type="checkbox"
                                            checked={form.outOfHub || false}
                                            onChange={(e) =>
                                                setForm({ ...form, outOfHub: e.target.checked })
                                            }
                                            style={{ width: 18, height: 18, cursor: "pointer" }}
                                        />
                                        <span
                                            style={{
                                                fontWeight: 600,
                                                color: form.outOfHub ? "#007bff" : "#333",
                                            }}
                                        >
                                            Out of Hub (Special Location)
                                        </span>
                                        {form.outOfHub && (
                                            <span style={{ fontSize: 18, color: "#007bff" }}>📍</span>
                                        )}
                                    </div>

                                    {form.outOfHub && (
                                        <div style={{ animation: "fadeIn 0.3s ease", marginBottom: 8 }}>
                                            <input
                                                type="text"
                                                placeholder="Specify custom location (e.g. Beach Set, Hotel, Offsite...)"
                                                value={form.outOfHubLocation || ""}
                                                onChange={(e) =>
                                                    setForm({ ...form, outOfHubLocation: e.target.value })
                                                }
                                                style={{
                                                    width: "100%",
                                                    padding: "9px 8px",
                                                    fontSize: 13.5,
                                                    borderRadius: 6,
                                                    border: "1px solid #bbb",
                                                }}
                                            />
                                        </div>
                                    )}

                                    {/* === PROJECT CODE + ENDING CODE === */}
                                    <div style={{ display: "flex", gap: 8, marginBottom: 8 }}>
                                        <div style={{ flex: 1 }}>
                                            <label style={{ display: "block", fontWeight: 600, marginBottom: 4 }}>
                                                PROJECT CODE <span style={{ color: "red" }}>*</span>
                                            </label>
                                            <input
                                                type="text"
                                                placeholder="E.g. G3XX"
                                                value={form.code}
                                                onChange={(e) => setForm({ ...form, code: e.target.value })}
                                                style={{
                                                    width: "100%",
                                                    padding: "9px 8px",
                                                    fontSize: 13.5,
                                                    borderRadius: 6,
                                                }}
                                            />
                                        </div>

                                        <div style={{ flex: 1 }}>
                                            <label style={{ display: "block", fontWeight: 600, marginBottom: 4 }}>
                                                ENDING CODE
                                            </label>
                                            <input
                                                type="text"
                                                placeholder="E.g. E-12"
                                                value={form.endingCode || ""}
                                                onChange={(e) => setForm({ ...form, endingCode: e.target.value })}
                                                style={{
                                                    width: "100%",
                                                    padding: "9px 8px",
                                                    fontSize: 13.5,
                                                    borderRadius: 6,
                                                }}
                                            />
                                        </div>
                                    </div>
                                </>
                            )}

                            {/* === DATE === */}
                            <label style={{ display: "block", fontWeight: 600, marginBottom: 4 }}>
                                DATE <span style={{ color: "red" }}>*</span>
                            </label>
                            <input
                                type="date"
                                value={form.date}
                                onChange={(e) => setForm({ ...form, date: e.target.value })}
                                style={{
                                    width: "100%",
                                    padding: "12px 8px",
                                    fontSize: 14,
                                    borderRadius: 6,
                                    marginBottom: 8,
                                    border: "1px solid #ccc",
                                    cursor: "pointer",
                                }}
                            />

                            {/* === REALITY CARD === */}
                            {form.isReality && (
                                <div
                                    style={{
                                        border: "1px solid #ccc",
                                        borderRadius: "8px",
                                        overflow: "hidden",
                                        width: "120px",
                                        textAlign: "center",
                                        margin: "10px auto 12px",
                                        boxShadow: "0 2px 5px rgba(0,0,0,0.15)",
                                    }}
                                >
                                    <div style={{ background: "#000", height: "20px", width: "100%" }}></div>
                                    <div
                                        style={{
                                            padding: "6px 0",
                                            fontWeight: "700",
                                            fontSize: "18px",
                                            color: "#000",
                                            letterSpacing: "1px",
                                        }}
                                    >
                                        REALITY
                                    </div>
                                </div>
                            )}

                            {/* === NOTE (sadece Reality değilken) === */}
                            {!form.isReality && (
                                <>
                                    <label style={{ display: "block", fontWeight: 600, marginBottom: 4 }}>
                                        NOTE
                                    </label>
                                    <textarea
                                        value={form.note}
                                        onChange={(e) =>
                                            setForm({ ...form, note: e.target.value })
                                        }
                                        placeholder="Optional note..."
                                        style={{
                                            width: "100%",
                                            padding: "9px 8px",
                                            fontSize: 13,
                                            borderRadius: 6,
                                            height: 60,
                                            marginBottom: 8,
                                        }}
                                    />
                                </>
                            )}

                            {/* === BUTTONS === */}
                            <div
                                style={{
                                    display: "flex",
                                    justifyContent: "space-between",
                                    alignItems: "center",
                                }}
                            >
                                {/* DRAFT BUTTON (her zaman görünür) */}
                                <button
                                    type="button"
                                    onClick={() => setForm({ ...form, isDraft: !form.isDraft })}
                                    style={{
                                        background: form.isDraft ? "#ffc107" : "#e9ecef",
                                        color: form.isDraft ? "#000" : "#444",
                                        border: "1px solid #ccc",
                                        padding: "8px 14px",
                                        borderRadius: 6,
                                        fontWeight: 600,
                                        cursor: "pointer",
                                        transition: "0.2s",
                                    }}
                                >
                                    {form.isDraft ? "✅ MARKED AS DRAFT" : "MARK AS DRAFT"}
                                </button>

                                {/* RIGHT BUTTON GROUP */}
                                <div style={{ display: "flex", gap: 8 }}>
                                    <button
                                        type="button"
                                        onClick={() =>
                                            setForm({ ...form, isReality: !form.isReality })
                                        }
                                        style={{
                                            background: form.isReality ? "#0d6efd" : "#e9ecef",
                                            color: form.isReality ? "#fff" : "#444",
                                            border: "1px solid #ccc",
                                            padding: "8px 14px",
                                            borderRadius: 6,
                                            fontWeight: 600,
                                            cursor: "pointer",
                                            transition: "0.2s",
                                        }}
                                    >
                                        {form.isReality ? "🎬 REALITY DAY ON" : "SET REALITY DAY"}
                                    </button>

                                    <button
                                        type="submit"
                                        style={{
                                            background: "#007bff",
                                            color: "#fff",
                                            padding: "8px 16px",
                                            borderRadius: 6,
                                            border: "none",
                                            cursor: "pointer",
                                            fontWeight: 600,
                                        }}
                                    >
                                        SAVE
                                    </button>

                                    <button
                                        type="button"
                                        onClick={() => setShowAddEvent(false)}
                                        style={{
                                            background: "#6c757d",
                                            color: "#fff",
                                            padding: "8px 16px",
                                            borderRadius: 6,
                                            border: "none",
                                            cursor: "pointer",
                                            fontWeight: 600,
                                        }}
                                    >
                                        CANCEL
                                    </button>
                                </div>
                            </div>
                        </form>
                    </div>
                </div>
            )}





            {/* === TAKVİM === */}
            <div
                style={{
                    position: "relative",
                    maxHeight: "75vh",
                    borderRadius: 6,
                }}
            >
                {/* ◀ Sol kaydır butonu */}
                <button
                    onClick={() => {
                        document.getElementById("calendarScrollX").scrollBy({
                            left: -300,
                            behavior: "smooth",
                        });
                    }}
                    style={{
                        position: "absolute",
                        left: 5,
                        top: "50%",
                        transform: "translateY(-50%)",
                        zIndex: 10,
                        background: "#343a40",
                        color: "white",
                        border: "none",
                        borderRadius: "50%",
                        width: 36,
                        height: 36,
                        cursor: "pointer",
                        opacity: 0.8,
                    }}
                >
                    ◀
                </button>

                {/* Takvim tablosu kaydırma alanı */}
                <div
                    id="calendarScrollX"
                    style={{
                        overflow: "auto",
                        maxHeight: "80vh",
                        scrollBehavior: "smooth",
                        borderRadius: 6,
                        position: "relative",
                    }}
                >

                    <table
                        style={{
                            borderCollapse: "collapse",
                            width: "100%",
                            fontSize: 13,
                            minWidth: 1000,
                        }}
                    >
                        <thead
                            style={{
                                position: "sticky",
                                top: 0,
                                zIndex: 10,
                                background: "#000000ff",
                            }}
                        >
                            <tr>
                                <th
                                    style={{
                                        position: "sticky",
                                        left: 0,
                                        top: 0,
                                        background: "#000000ff",
                                        color: "#fff",
                                        fontWeight: "900",
                                        textTransform: "uppercase",
                                        minWidth: 180,
                                        zIndex: 6,
                                        borderRight: "1px solid #999",
                                        letterSpacing: "0.8px",
                                        padding: 6,
                                    }}
                                >
                                    <div style={{ display: "flex", flexDirection: "column", gap: 4 }}>
                                        <span style={{ fontSize: 12, textAlign: "center" }}>PROJECT / DATE</span>
                                        <select
                                            value={selectedProjectFilter}
                                            onChange={(e) => setSelectedProjectFilter(e.target.value)}
                                            style={{
                                                fontSize: 12,
                                                padding: "3px 4px",
                                                borderRadius: 4,
                                                border: "1px solid #666",
                                                background: "#000000ff",
                                                color: "#fff",
                                                cursor: "pointer",
                                            }}
                                        >
                                            <option value="all">All Projects</option>
                                            <option value="Survivor">Survivor</option>
                                            <option value="Exatlon ">Exatlon</option>
                                        </select>
                                    </div>
                                </th>

                                {days.map((d) => {
                                    const isSunday = d.getDay() === 0; // ✅ Pazar = 0

                                    return (
                                        <th
                                            key={d}
                                            style={{
                                                background: isSunday ? "#fff3cd" : "#000000", // ✅ Pazar sarı
                                                color: isSunday ? "#000" : "#fff",
                                                fontWeight: 800,
                                                border: "1px solid #999",
                                                minWidth: 140,
                                                padding: "8px 4px",
                                                textTransform: "uppercase",
                                                letterSpacing: "0.3px",
                                                position: "sticky",
                                                top: 0,
                                                zIndex: 5,
                                            }}
                                        >
                                            {d.toLocaleDateString("en-GB", { day: "2-digit", month: "2-digit" })}
                                            <div style={{ fontSize: 11, opacity: 0.85 }}>
                                                {d.toLocaleDateString("en-GB", { weekday: "short" }).toUpperCase()}
                                            </div>
                                        </th>
                                    );
                                })}


                            </tr>
                        </thead>
                        <tbody>
                            {PROJECTS.filter((proj) =>
                                selectedProjectFilter === "all"
                                    ? true
                                    : proj.name.toLowerCase().includes(selectedProjectFilter.toLowerCase())
                            ).map((proj) => (


                                <tr key={proj.name}>
                                    {/* Sol sütun: Bayrak + Proje ismi */}
                                    <td
                                        style={{
                                            position: "sticky",
                                            left: 0,
                                            background: "rgb(213, 213, 213)",
                                            borderRight: "1px solid #999",
                                            minWidth: 130,
                                            zIndex: 4,
                                            textAlign: "center",
                                            padding: "10px 6px",
                                        }}
                                    >
                                        <div
                                            style={{
                                                display: "flex",
                                                flexDirection: "column",
                                                alignItems: "center",
                                                justifyContent: "center",
                                                gap: 8,
                                            }}
                                        >
                                            {/* Bayrak */}
                                            <img
                                                src={proj.flag}
                                                alt={`${proj.name} flag`}
                                                style={{
                                                    width: 55,
                                                    height: 55,
                                                    borderRadius: "50%",
                                                    boxShadow: "0 0 8px rgba(0,0,0,0.4)",
                                                    objectFit: "cover",
                                                    background: "#fff",
                                                    transition: "transform 0.2s ease, box-shadow 0.2s ease",
                                                    cursor: "pointer",
                                                }}
                                                onMouseOver={(e) => {
                                                    e.currentTarget.style.transform = "scale(1.08)";
                                                    e.currentTarget.style.boxShadow = "0 0 12px rgba(0,0,0,0.6)";
                                                }}
                                                onMouseOut={(e) => {
                                                    e.currentTarget.style.transform = "scale(1)";
                                                    e.currentTarget.style.boxShadow = "0 0 8px rgba(0,0,0,0.4)";
                                                }}
                                            />

                                            {/* Sadece Survivor veya Exathlon yazısı */}
                                            <span
                                                style={{
                                                    fontWeight: 800,
                                                    fontSize: 15,
                                                    color: "#000",
                                                    textTransform: "uppercase",
                                                    letterSpacing: "0.6px",
                                                }}
                                            >
                                                {getProjectDisplayName(proj.name)}
                                            </span>


                                        </div>
                                    </td>


                                    {/* Sağ taraf: Günlük hücreler */}
                                    {days.map((d) => {
                                        const dateStr = ymd(d);
                                        const todays = events.filter(
                                            (ev) => ev.project === proj.name && ev.date === dateStr
                                        );

                                        // ✅ Pazar kontrolü ekledik
                                        const isSunday = d.getDay() === 0;

                                        return (
                                            <td
                                                key={proj.name + dateStr}
                                                onDrop={(e) => onDropToCell(e, dateStr, proj.name)}
                                                onDragOver={(e) => e.preventDefault()}
                                                style={{
                                                    border: "1px solid #ccc",
                                                    minWidth: 140,
                                                    height: 110,
                                                    verticalAlign: "top",
                                                    background: isSunday ? "#fff3cd" : "#fff", // ✅ Pazar tam kolon sarı!
                                                }}
                                            >

                                                {todays.map((ev) => {
                                                    const { bg, fg } = getZoneColors(ev.zone);
                                                    let moved = false; // drag yapıldı mı kontrolü

                                                    return (
                                                        <div
                                                            key={ev.id}
                                                            draggable
                                                            onDragStart={(e) => {
                                                                moved = true;
                                                                e.dataTransfer.setData("application/json", JSON.stringify(ev));
                                                            }}
                                                            onDragEnd={() => (moved = false)}
                                                            onClick={() => {
                                                                if (!moved) handleOpenEvent(ev);
                                                            }}
                                                            style={{
                                                                background: ev.isReality ? "#fff" : "#fff",
                                                                color: "#000",
                                                                borderRadius: 10,
                                                                boxShadow: ev.isReality
                                                                    ? "0 2px 5px rgba(0,0,0,0.25)"
                                                                    : "0 2px 5px rgba(0,0,0,0.25)",
                                                                marginBottom: 8,
                                                                overflow: "hidden",
                                                                border: ev.isReality ? "1.5px solid #ccc" : `2px solid ${bg}`,
                                                                cursor: "grab",
                                                                userSelect: "none",
                                                            }}
                                                            title={ev.note}
                                                        >
                                                            {/* === REALITY KART === */}
                                                            {ev.isReality ? (
                                                                <div
                                                                    style={{
                                                                        width: "100%",
                                                                        borderRadius: 8,
                                                                        overflow: "hidden",
                                                                        textAlign: "center",
                                                                        boxShadow: "0 2px 5px rgba(0,0,0,0.25)",
                                                                    }}
                                                                >
                                                                    {/* Üst siyah şerit */}
                                                                    <div style={{ background: "#000", height: "22px", width: "100%" }}></div>

                                                                    {/* Orta “REALITY” yazısı */}
                                                                    <div
                                                                        style={{
                                                                            background: "#fff",
                                                                            color: "#000",
                                                                            fontWeight: 800,
                                                                            fontSize: 16,
                                                                            padding: "8px 0",
                                                                            letterSpacing: "1px",
                                                                        }}
                                                                    >
                                                                        REALITY
                                                                    </div>

                                                                    {/* Alt bilgi (not varsa gösterelim) */}
                                                                    {(ev.note || ev.endingCode) && (
                                                                        <div
                                                                            style={{
                                                                                fontSize: 11.5,
                                                                                marginTop: 2,
                                                                                fontStyle: "italic",
                                                                                opacity: 0.9,
                                                                            }}
                                                                        >
                                                                            {ev.note}
                                                                            {ev.endingCode && `  / ${ev.endingCode}`}
                                                                        </div>
                                                                    )}

                                                                </div>
                                                            ) : (
                                                                <>
                                                                    {/* === NORMAL EVENT === */}
                                                                    {/* ZONE Header */}
                                                                    <div
                                                                        style={{
                                                                            background: bg,
                                                                            color: fg,
                                                                            padding: "3px 6px",
                                                                            fontSize: 11,
                                                                            fontWeight: 800,
                                                                            textTransform: "uppercase",
                                                                            letterSpacing: "0.5px",
                                                                        }}
                                                                    >
                                                                        {ev.zone}
                                                                    </div>

                                                                    {/* İçerik */}
                                                                    <div
                                                                        style={{
                                                                            padding: "8px 10px",
                                                                            fontSize: 12.5,
                                                                            lineHeight: 1.3,
                                                                        }}
                                                                    >
                                                                        <div style={{ fontWeight: 700 }}>{ev.location}</div>
                                                                        <div style={{ fontSize: 12, fontWeight: 700 }}>{ev.code}</div>
                                                                        {(ev.note || ev.endingCode) && (
                                                                            <div
                                                                                style={{
                                                                                    fontSize: 11.5,
                                                                                    marginTop: 2,
                                                                                    fontStyle: "italic",
                                                                                    opacity: 0.9,
                                                                                }}
                                                                            >
                                                                                {ev.note}
                                                                                {ev.endingCode && `  / ${ev.endingCode}`}
                                                                            </div>
                                                                        )}

                                                                    </div>

                                                                    {/* Footer etiketi (Draft / Revised) */}
                                                                    <div
                                                                        style={{
                                                                            borderTop: "1px solid #ccc",
                                                                            padding: "4px 6px",
                                                                            textAlign: "right",
                                                                        }}
                                                                    >
                                                                        {ev.isRevised ? (
                                                                            <span
                                                                                style={{
                                                                                    background: "#dc3545",
                                                                                    color: "white",
                                                                                    fontSize: 10.5,
                                                                                    padding: "2px 6px",
                                                                                    borderRadius: 6,
                                                                                    fontWeight: 700,
                                                                                }}
                                                                            >
                                                                                REVISED
                                                                            </span>
                                                                        ) : ev.isDraft ? (
                                                                            <span
                                                                                style={{
                                                                                    background: "#6c757d",
                                                                                    color: "white",
                                                                                    fontSize: 10.5,
                                                                                    padding: "2px 6px",
                                                                                    borderRadius: 6,
                                                                                    fontWeight: 700,
                                                                                }}
                                                                            >
                                                                                DRAFT
                                                                            </span>
                                                                        ) : null}
                                                                    </div>
                                                                </>
                                                            )}
                                                        </div>

                                                    );
                                                })}



                                            </td>
                                        );
                                    })}
                                </tr>
                            ))}
                        </tbody>

                    </table>
                </div>

                {/* === MODAL === */}
                {selectedEvent && (
                    <div
                        style={{
                            position: "fixed",
                            top: 0,
                            left: 0,
                            width: "100%",
                            height: "100%",
                            background: "rgba(0,0,0,0.4)",
                            display: "flex",
                            justifyContent: "center",
                            alignItems: "center",
                            zIndex: 999,
                        }}
                    >
                        <div
                            style={{
                                background: "#fff",
                                padding: 20,
                                borderRadius: 10,
                                width: 400,
                                boxShadow: "0 5px 15px rgba(0,0,0,0.3)",
                            }}
                        >
                            <h3 style={{ marginBottom: 10 }}>{selectedEvent.project}</h3>
                            <p><b>Zone:</b> {selectedEvent.zone}</p>
                            <p><b>Location:</b> {selectedEvent.location}</p>

                            {/* 📅 Date */}
                            <label><b>Date:</b></label>
                            <input
                                type="date"
                                value={selectedEvent.date}
                                onChange={(e) =>
                                    setSelectedEvent({
                                        ...selectedEvent,
                                        date: e.target.value,
                                        isRevised: true,
                                    })
                                }
                                style={{
                                    width: "100%",
                                    marginTop: 4,
                                    padding: "6px 8px",
                                    borderRadius: 6,
                                    border: "1px solid #ccc",
                                    marginBottom: 10,
                                }}
                            />

                            {/* 🔢 Ending Code */}
                            <label><b>Ending Code:</b></label>
                            <input
                                type="text"
                                value={selectedEvent.endingCode || ""}
                                onChange={(e) =>
                                    setSelectedEvent({ ...selectedEvent, endingCode: e.target.value })
                                }
                                style={{
                                    width: "100%",
                                    marginTop: 4,
                                    padding: "6px 8px",
                                    borderRadius: 6,
                                    border: "1px solid #ccc",
                                    marginBottom: 10,
                                }}
                                placeholder="Enter ending code..."
                            />

                            {/* 📝 Note */}
                            <label><b>Note:</b></label>
                            <textarea
                                value={selectedEvent.note}
                                onChange={(e) =>
                                    setSelectedEvent({ ...selectedEvent, note: e.target.value })
                                }
                                style={{
                                    width: "100%",
                                    height: 60, // sabit yükseklik
                                    resize: "none", // büyümesin
                                    borderRadius: 6,
                                    border: "1px solid #ccc",
                                    marginTop: 4,
                                    overflowY: "auto", // taşarsa scroll
                                }}
                            />

                            {/* 🔘 Buttons */}
                            <div style={{ display: "flex", justifyContent: "space-between", marginTop: 15 }}>
                                <button
                                    onClick={handleSaveRevisedEvent}
                                    style={{
                                        background: "#007bff",
                                        color: "white",
                                        border: "none",
                                        borderRadius: 6,
                                        padding: "6px 14px",
                                        cursor: "pointer",
                                    }}
                                >
                                    Save
                                </button>
                                <button
                                    onClick={handleCopyEvent}
                                    style={{
                                        background: "#ffc107",
                                        color: "#000",
                                        border: "none",
                                        borderRadius: 6,
                                        padding: "6px 14px",
                                        cursor: "pointer",
                                    }}
                                >
                                    Copy
                                </button>
                                <button
                                    onClick={() => handleDeleteEvent(selectedEvent.id)}
                                    style={{
                                        background: "#dc3545",
                                        color: "white",
                                        border: "none",
                                        borderRadius: 6,
                                        padding: "6px 14px",
                                        cursor: "pointer",
                                    }}
                                >
                                    Delete
                                </button>
                                <button
                                    onClick={() => setSelectedEvent(null)}
                                    style={{
                                        background: "#6c757d",
                                        color: "white",
                                        border: "none",
                                        borderRadius: 6,
                                        padding: "6px 14px",
                                        cursor: "pointer",
                                    }}
                                >
                                    Close
                                </button>
                            </div>
                        </div>
                    </div>
                )}


                {/* ▶ Sağ kaydır butonu */}
                <button
                    onClick={() => {
                        document.getElementById("calendarScrollX").scrollBy({
                            left: 300,
                            behavior: "smooth",
                        });
                    }}
                    style={{
                        position: "absolute",
                        right: 5,
                        top: "50%",
                        transform: "translateY(-50%)",
                        zIndex: 10,
                        background: "#343a40",
                        color: "white",
                        border: "none",
                        borderRadius: "50%",
                        width: 36,
                        height: 36,
                        cursor: "pointer",
                        opacity: 0.8,
                    }}
                >
                    ▶
                </button>
            </div>

        </div>
    );
}


