import React, { useEffect, useState } from "react";
import { onAuthStateChanged, signOut } from "firebase/auth";
import { auth } from "./firebase/config";
import LoginPage from "./pages/LoginPage";
import CalendarPage from "./pages/CalendarPage";
import ChangeLogsPage from "./pages/ChangeLogsPage";
import AllEventsPage from "./pages/AllEventsPage";
import logo from "./assets/AcunMedya-Logo.png";
import "./App.css";

export default function App() {
  const [user, setUser] = useState(null);
  const [activeTab, setActiveTab] = useState("CALENDAR");

  // 🔹 Üst bar butonlarının kontrol ettiği state'ler
  const [viewMode, setViewMode] = useState("twoweeks");
  const [forceAddEvent, setForceAddEvent] = useState(false);

  // 🔹 Firebase login dinleyicisi
  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, setUser);
    return () => unsubscribe();
  }, []);

  if (!user) return <LoginPage auth={auth} />;

  const TABS = [
    { key: "CALENDAR", label: "TAKVİM" },
    { key: "CHANGE LOGS", label: "DEĞİŞİKLİKLER" },
    { key: "ALL EVENTS", label: "ETKİNLİKLER" },
  ];

  // 🔹 PDF export (şimdilik stub)
  const handleExportPDF = () => {
    alert("📄 PDF export fonksiyonu eklenecek!");
  };

  return (
    <div
      className="App"
      style={{
        background: "#f8f9fa",
        minHeight: "100vh",
        display: "flex",
        flexDirection: "column",
      }}
    >
      {/* === ÜST BAR === */}
      <header
        style={{
          position: "sticky",
          top: 0,
          zIndex: 1000,
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          background: "#fff",
          boxShadow: "0 2px 6px rgba(0,0,0,0.08)",
          padding: "8px 16px",
          flexWrap: "wrap",
        }}
      >
        {/* Logo */}
        <img src={logo} alt="Acun Medya" style={{ width: 140 }} />

        {/* Sekmeler ve Event butonları */}
        <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
          {TABS.map((tab) => (
            <button
              key={tab.key}
              onClick={() => setActiveTab(tab.key)}
              style={{
                background: activeTab === tab.key ? "#007bff" : "#f8f9fa",
                color: activeTab === tab.key ? "#fff" : "#333",
                fontWeight: 600,
                padding: "6px 12px",
                fontSize: 12,
                borderRadius: 6,
                border: "1px solid #ccc",
                cursor: "pointer",
                transition: "0.2s",
              }}
            >
              {tab.label}
            </button>
          ))}

        </div>

        {/* Kullanıcı bilgisi ve çıkış */}
        <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
          <span style={{ fontWeight: 500, fontSize: 12 }}>
            {user?.email?.toUpperCase()}
          </span>
          <button
            onClick={() => signOut(auth)}
            style={{
              background: "#dc3545",
              color: "#fff",
              border: "none",
              padding: "5px 10px",
              borderRadius: 6,
              fontSize: 12,
              fontWeight: 600,
              cursor: "pointer",
            }}
          >
            SIGN OUT
          </button>
        </div>
      </header>

      {/* === SAYFA İÇERİĞİ === */}
      <div style={{ flex: 1, padding: "10px 20px 40px", overflowY: "auto" }}>
        {activeTab === "CALENDAR" && (
          <CalendarPage
            user={user}
            viewMode={viewMode}
            forceAddEvent={forceAddEvent}
            onCloseAddEvent={() => setForceAddEvent(false)}
          />
        )}
        {activeTab === "CHANGE LOGS" && <ChangeLogsPage />}
        {activeTab === "ALL EVENTS" && <AllEventsPage />}
      </div>
    </div>
  );
}
