import React, { useEffect, useState } from "react";
import { db } from "../firebase/config";
import { collection, onSnapshot } from "firebase/firestore";
import * as XLSX from "xlsx";
import { saveAs } from "file-saver";

export default function ChangeLogsPage() {
  const [logs, setLogs] = useState([]);

  useEffect(() => {
    const unsub = onSnapshot(collection(db, "changeLogs"), (snap) => {
      const data = snap.docs.map((d) => ({
        id: d.id,
        ...d.data(),
      }));
      setLogs(
        data.sort((a, b) => (b.time || "").localeCompare(a.time || ""))
      );
    });
    return () => unsub();
  }, []);

  const exportExcel = () => {
    const ws = XLSX.utils.json_to_sheet(logs);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "ChangeLogs");
    const buf = XLSX.write(wb, { bookType: "xlsx", type: "array" });
    saveAs(new Blob([buf]), "ChangeLogs.xlsx");
  };

  return (
    <div style={{ padding: 20 }}>
      <h3>🧾 Change Logs</h3>

      {logs.length > 0 && (
        <button
          onClick={exportExcel}
          style={{
            background: "#28a745",
            color: "#fff",
            marginBottom: 10,
            border: "none",
            padding: "6px 12px",
            borderRadius: 6,
            cursor: "pointer",
          }}
        >
          📥 Export Excel
        </button>
      )}

      <div className="table-container" style={{ overflowX: "auto" }}>
        <table style={{ width: "100%", borderCollapse: "collapse" }}>
          <thead>
            <tr>
              <th>Project</th>
              <th>Zone</th>
              <th>Location</th>
              <th>Old Date</th>
              <th>New Date</th>
              <th>Reason</th>
              <th>User</th>
              <th>Time</th>
              <th>Status</th> {/* ✅ Yeni sütun */}
            </tr>
          </thead>
          <tbody>
            {logs.map((l, i) => (
              <tr key={i}>
                <td>{l.project}</td>
                <td>{l.zone}</td>
                <td>{l.location}</td>
                <td>{l.oldDate}</td>
                <td>{l.newDate}</td>
                <td>{l.reason}</td>
                <td>{l.user}</td>
                <td>{l.time}</td>
                <td>
                  {/* ✅ Status bilgisi renklendirilmiş şekilde */}
                  <span
                    style={{
                      color:
                        l.operation === "Deleted"
                          ? "#dc3545"
                          : l.operation?.includes("Updated")
                          ? "#007bff"
                          : l.operation === "Created"
                          ? "#28a745"
                          : "#333",
                      fontWeight: "bold",
                    }}
                  >
                    {l.operation || l.status || "-"}
                  </span>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}
