import React, { useState } from "react";
import { signInWithEmailAndPassword } from "firebase/auth";
import logo from "../assets/AcunMedya-Logo.png";

export default function LoginPage({ auth }) {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");

  const handleLogin = async (e) => {
    e.preventDefault();
    try {
      await signInWithEmailAndPassword(auth, email, password);
    } catch (err) {
      alert("LOGIN FAILED: " + err.message.toUpperCase());
    }
  };

  return (
    <div style={{
      display: "flex", flexDirection: "column",
      alignItems: "center", justifyContent: "center",
      height: "100vh", background: "#0d0d0d", color: "white"
    }}>
      <img src={logo} alt="Acun Medya Logo" style={{ width: 220, marginBottom: 40 }} />
      <h2> SIGN IN TO CALENDAR</h2>
      <form onSubmit={handleLogin} style={{ display: "flex", flexDirection: "column", gap: 10, width: 320 }}>
        <input type="email" placeholder="EMAIL" value={email} onChange={(e) => setEmail(e.target.value)} required />
        <input type="password" placeholder="PASSWORD" value={password} onChange={(e) => setPassword(e.target.value)} required />
        <button type="submit" style={{ background: "#000000ff", color: "#fff", border: "none", padding: "10px", borderRadius: "6px", fontWeight: "bold" }}>
          SIGN IN
        </button>
      </form>
    </div>
  );
}
